#nullable enable // autogenerated

using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Localization
{
    public class ResourcePackReaderZipV1 : ResourcePackReaderV1, IResourcePackReaderZip
    {
        public ResourcePackReaderZipV1(MainManager main) : base(main)
        {
        }
        public override ResourcePack? ReadPack(string key, string path)
        {
            using var stream = File.Open(path, FileMode.Open);
            return ReadPack(key, stream);
        }
        public ResourcePack? ReadPack(string key, byte[] bytes)
        {
            using var memory = new MemoryStream(bytes);
            return ReadPack(key, memory);
        }
        public ResourcePack? ReadPack(string key, Stream stream)
        {
            try
            {
                // 新建一个资源包实例。
                using var archive = new ZipArchive(stream);
                var pack = new ResourcePack(key);

                // manifest条目。
                var manifestEntry = archive.GetEntry(MANIFEST_FILENAME);

                // 将manifest读取到内存。
                var manifest = LoadManifest(manifestEntry);
                if (manifest == null)
                {
                    throw new FileNotFoundException($"The file {MANIFEST_FILENAME} in resource pack {key} is missing!");
                }
                // 从manifest中读取资源包内容。
                LoadFromManifest(archive, manifest, pack, key);
                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包Zip失败：{e}");
                return null;
            }
        }
        private ResourcePackManifest? LoadManifest(ZipArchiveEntry entry)
        {
            // 加载Sprite Manifest文件。
            if (entry == null)
                return null;
            var manifestJson = entry.ReadString(Encoding.UTF8);
            return JsonConvert.DeserializeObject<ResourcePackManifest>(manifestJson);
        }
        private void LoadFromManifest(ZipArchive archive, ResourcePackManifest manifest, ResourcePack pack, string key)
        {
            // 加载翻译文件。
            LoadCatalogsFromManifest(archive, manifest, pack);

            // 加载贴图。
            LoadSpritesFromManifest(archive, manifest, pack, key);
        }

        private void LoadCatalogsFromManifest(ZipArchive archive, ResourcePackManifest manifest, ResourcePack pack)
        {
            if (manifest.localization == null)
                return;

            if (manifest.localization.languages != null)
            {
                foreach (var language in manifest.localization.languages)
                {
                    // 语言代码。
                    var code = language.code;
                    if (string.IsNullOrEmpty(code))
                        continue;

                    if (language.catalogs != null)
                    {
                        foreach (var relativePath in language.catalogs)
                        {
                            // 获取catalog的路径，并加载。
                            var catalogPath = Path.Combine("assets", relativePath).Replace("\\", "/");
                            var catalogEntry = archive.GetEntry(catalogPath);
                            var catalog = catalogEntry.ReadCatalog(code);

                            // 将加载后的catalog注册。
                            var packCatalogs = pack.GetOrCreateLanguageCatalogs(code);
                            var filenameWithoutExt = Path.GetFileNameWithoutExtension(catalogPath);
                            packCatalogs.catalogs.Add(filenameWithoutExt, catalog);
                        }
                    }
                }
            }
        }

        private void LoadSpritesFromManifest(ZipArchive archive, ResourcePackManifest manifest, ResourcePack pack, string key)
        {
            // 加载贴图
            if (manifest.textures == null)
                return;

            var generatedCategory = GetLanguagePackSpriteCategory(key);

            foreach (var packTexture in manifest.textures)
            {
                if (string.IsNullOrEmpty(packTexture.texture))
                    continue;

                // 获取贴图路径。
                var texturePath = Path.Combine("assets", packTexture.texture).Replace("\\", "/");

                // 文件不存在，直接跳过。
                if (!File.Exists(texturePath))
                    continue;

                var slices = packTexture.slices;
                if (slices == null)
                    continue;

                // 尝试获取资源包中的这个texture对象。
                // 如果没有获取到，新建一个。
                if (!pack.textures.TryGetValue(texturePath, out var texture))
                {
                    var textureEntry = archive.GetEntry(texturePath);
                    texture = ReadTexture2DZip(textureEntry);
                    pack.textures.Add(texturePath, texture);
                }

                // 获取ID和图片标签。
                var splitTexturePaths = Path.ChangeExtension(packTexture.texture, string.Empty).TrimEnd('.').Split('/', '\\');
                string nsp, textureId;
                if (splitTexturePaths.Length > 1)
                {
                    nsp = splitTexturePaths[0];
                    textureId = string.Join("/", splitTexturePaths.Skip(1));
                }
                else
                {
                    nsp = string.Empty;
                    textureId = string.Join("/", splitTexturePaths);
                }
                var splitTagTexturePaths = textureId.Split("@");
                textureId = splitTagTexturePaths[0];
                var tags = splitTagTexturePaths.Skip(1).ToArray();

                // 加载贴图。
                for (int i = 0; i < slices.Length; i++)
                {
                    var slice = slices[i];
                    var spriteRef = slice.replaces;
                    if (spriteRef == null)
                    {
                        if (string.IsNullOrEmpty(nsp))
                        {
                            Log.LogWarning($"Cannot load sprite {packTexture.texture} from resource pack: Invalid file path.");
                            continue;
                        }
                        var spriteID = new NamespaceID(nsp, textureId);
                        spriteRef = new SpriteReference(spriteID, i);
                    }
                    var spriteKey = new SpriteLookupKey(spriteRef, tags);
                    var sprite = CreateSprite(texture, slice, spriteKey.ToString(), generatedCategory);
                    pack.AddSprite(spriteKey, sprite);
                }
            }
        }
        private Texture2D ReadTexture2DZip(ZipArchiveEntry textureEntry, string name = "texture2D")
        {
            var bytes = textureEntry.ReadBytes();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
